        `,actionSteps:["Bitta 'Before / After' (Oldin / Keyin) formatidagi video ssenariy yozing.","Haftasiga kamida 3 ta foydali Reels joylashni rejalashtiring."],quiz:[{question:"Reels videosida tomoshabinni ushlab qoluvchi eng muhim vaqt oralig'i qaysi?",options:["Dastlabki 3 soniya","Eng oxirgi soniya","15-daqiqada","Video tugagandan keyin"],correctAnswer:0,explanation:"Birinchi 3 soniyada tomoshabin qiziqsa, videoni oxirigacha tomosha qiladi."}]},{id:"l3-4",number:4,title:"Direct va Telegramda Xushmuomala Sotuv Yozishmalari",duration:"25 daqiqa",overview:"Mijoz 'Narxi qancha?' deb so'raganda birdan narx aytib cho'chitmaslik va mehr bilan maslahat berish usullari.",notes:`
